/* equates for rAppInfo */#define rAppInfo			$802B#define rFinderPath			$802C#define LaunchThis			$1#define DontLaunch			$0#define reads				$10#define writes				$20#define native				$40#define creator				$80#define Filetype			$1#define	AuxType				$2#define Filename			$4#define CreateDateTime		$8#define ModDateTime			$10#define LocalAccess			$20#define NetworkAccess		$40#define Where				$80#define HFSFileType			$100#define HFSCreator			$200#define OptionList			$400/*------------------------------ rAppInfo ----------------------------------------*/type rAppInfo {start:		integer = 0;				/* version must be zero 			*/		integer = (list-start)/8;	/* offset to document list 			*/		longint;					/* rIcon ID for application 		*/list:		integer = $$countOf(OneDocs);		array OneDocs {startOneDoc:			integer = (end[$$ArrayIndex(OneDocs)]-startOneDoc[$$ArrayIndex(OneDocs)])/8;														/* size in bytes of this structure 	*/						integer = (matchFlags[$$ArrayIndex(OneDocs)]-startOneDoc[$$ArrayIndex(OneDocs)])/8;												/* offset to MatchFlags field from */			integer = $$optionalCount(Results);												/* pCount for results			*/			optional Results {				integer;			/* bit 0 = launch this = boolean			*/									/* bits 4-7 = voting clout					*/				longint;			/* rFinderPath ID for this document			*/				longint;			/* rIcon ID for large icon for this doc		*/				longint;			/* rIcon ID for small icon for document		*/				pstring;			/* string to describe this type of document */			};			matchFlags: 			longint;				/* actually, just bits to say what follows so that									   andy doesn't have to traverse the following fields									   trying to determine what's there			*//*------------------- first field -----------------------------*/				switch {							case MatchFileType:					key integer = 0x1;					array [1] {						integer;			/* filetype to match 			*/ 					};					case empty:					key integer = 0x0;				};				/*--------------------- second field -------------------------*/								switch {							case MatchAuxType:					key integer = 0x2;					array [1] {						longint;			/* auxtype mask					*/						longint;			/* auxtype to match 			*/									};								case empty:					key integer = 0x0;				};/*--------------------- third field -------------------------*/								switch {											case MatchFileName:					key integer = 0x3;					array [1] {						pstring;					/* filename string 				*/					};				case empty:					key integer = 0x0;									};/*--------------------- fourth field -------------------------*/								switch {							case MatchCreateDate:					key integer = 0x4;					array [1] {						bitstring[16]	CompareSecond 	= 0x1,	/* do the comparison */										CompareMinute 	= 0x2,	/* how?				 */										CompareHour		= 0x4,										CompareYear		= 0x8,										CompareDay		= 0x10,										CompareMonth	= 0x20,										CompareWeekday	= 0x80,										lessThan		= 0x0,										equal			= 0x0100,										greater			= 0x0200,										not				= 0x0400;							hex string [8];						/* the date and time	*/					};								case empty:					key integer = 0x0;				};				/*--------------------- fifth field -------------------------*/								switch {											case MatchModDate:					key integer = 0x5;					array [1] {						bitstring[16]	CompareSecond 	= 0x1,	/* do the comparison */										CompareMinute 	= 0x2,	/* how?				 */										CompareHour		= 0x4,										CompareYear		= 0x8,										CompareDay		= 0x10,										CompareMonth	= 0x20,										CompareWeekday	= 0x80,										lessThan		= 0x0,										equal			= 0x0100,										greater			= 0x0200,										not				= 0x0400;							hex string [8];						/* the date and time	*/					};								case empty:					key integer = 0x0;				};								/*--------------------- sixth field -------------------------*/								switch {											case MatchLocalAccess:					key integer = 0x6;					array [1] {						integer;					/* access word mask				*/						integer;					/* access word comparison value */					};						case empty:					key integer = 0x0;				};				/*--------------------- seventh field -------------------------*/								switch {											case MatchNetworkAccess:					key integer = 0x7;					array [1] {						longint;					/* access word mask				*/						longint;					/* access word comparison value */					};						case empty:					key integer = 0x0;				};/*--------------------- eighth field -------------------------*/								switch {											case MatchWhere:					key integer = 0x8;					array [1] {						integer;					/* is the file extended? 		*/					};									case empty:					key integer = 0x0;				};/*--------------------- ninth field -------------------------*/								switch {											case MatchHFSFileType:					key integer = 0x9;					array [1] {						longint;					/* hfs filetype 				*/					};									case empty:					key integer = 0x0;					};				/*--------------------- tenth field -------------------------*/								switch {											case MatchHFSCreator:					key integer = 0xA;					array [1] {						longint;					/* hfs creator type 			*/					};				case empty:					key integer = 0x0;					};/*--------------------- eleventh field -------------------------*/								switch {											case MatchFSTOptions:					key integer = 0xB;					array [1] {						integer = $$countof(GroupOptions);						array GroupOptions {							integer = $$countof(filesystems);							array filesystems {								integer;			/* file sys ID 					*/							};						integer;				/* offset into option_list 				*/						longint;				/* mask for long fetched from option_list 	*/						longint;				/* comparison value for the masked long	*/						bitstring[16];			/* comparison specification				*/						};					};									case empty:					key integer = 0x0;				};/*------------------------------------------------------------*/				end:		};};/*------------------------------ rFinderPaths ----------------------------------------*/type rFinderPath {start:		integer = 0;				/* version must be zero 				*/		integer = (path-start)/8;	/* offset to pathname 					*/		integer = $$optionalCount(stuff);		optional Stuff {				longint;			/* rVersion ID of the owner app			*/		};path:		wstring;					/* wstring for application pathname		*/};